//! Table grid invariants and cell resolution.

use std::sync::Arc;

use rich_editor_auy::model::{
    Attr, AttrValue, Attrs, Block, CellRef, Doc, InlineItem, MarkSet, NodeKind, Run, TextBlock,
};
use rich_editor_auy::pos::Pos;
